#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace DeliveryService.Mok.Editor {
public static class RoleVisualUpgrade {
 const string Hoodie="Assets/Synty/PolygonCity/Prefabs/Characters/Character_Male_Hoodie.prefab";
 static void Player(PlayerAvatar a,string key){
 SyntyStoryUpgrade.Skin(a.transform,Hoodie,key,false,true);var rs=a.GetComponentsInChildren<SkinnedMeshRenderer>(true);var upper=rs[0];var lower=rs[1];var whole=upper.sharedMesh;
 var legs=new System.Collections.Generic.HashSet<Transform>();foreach(var bone in new[]{HumanBodyBones.LeftUpperLeg,HumanBodyBones.RightUpperLeg})foreach(var t in a.animator.GetBoneTransform(bone).GetComponentsInChildren<Transform>())legs.Add(t);
 bool Leg(int vertex){var w=whole.boneWeights[vertex];return legs.Contains(upper.bones[w.boneIndex0]);}
 for(int part=0;part<2;part++){var mesh=UnityEngine.Object.Instantiate(whole);for(int sub=0;sub<mesh.subMeshCount;sub++){var src=whole.GetTriangles(sub);var list=new System.Collections.Generic.List<int>();for(int i=0;i<src.Length;i+=3){bool leg=Leg(src[i])&&Leg(src[i+1])&&Leg(src[i+2]);if(leg==(part==1)){list.Add(src[i]);list.Add(src[i+1]);list.Add(src[i+2]);}}mesh.SetTriangles(list,sub);}var path="Assets/Scripts/Mok/Art/SyntyStory/"+key+(part==0?"-Upper":"-Lower")+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);mesh=saved;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,path);var dest=part==0?upper:lower;dest.sharedMesh=mesh;dest.bones=upper.bones;dest.rootBone=upper.rootBone;dest.sharedMaterials=upper.sharedMaterials;dest.localBounds=upper.localBounds;dest.enabled=true;}
 foreach(var r in a.GetComponentsInChildren<MeshRenderer>(true))r.enabled=false;a.upperBody=new Renderer[]{upper};EditorUtility.SetDirty(a);
 }
 public static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");
 var main=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");if(!main.isLoaded)main=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);
 EditorSceneManager.SaveScene(main,"Logs/Main-before-role-"+stamp+".unity",true);
 foreach(var a in main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlayerAvatar>(true)))Player(a,"PlayerMain");
 var finale=main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VenueFinale>(true)).Single();var broker=finale.preparation.preparation.delivery.broker;
 int i=0;foreach(var e in new[]{broker.enemyTemplate,finale.preparation.enemyTemplate}.Distinct()){
 SyntyStoryUpgrade.Skin(e.transform,"Assets/Synty/PolygonCity/Prefabs/Characters/Character_BusinessMan_Shirt.prefab","GangDistinct"+i);
 foreach(var r in e.GetComponentsInChildren<SkinnedMeshRenderer>()){var mats=r.sharedMaterials;for(int m=0;m<mats.Length;m++){var mat=new Material(mats[m]);mat.color=new Color(.32f,.36f,.42f);AssetDatabase.CreateAsset(mat,"Assets/Scripts/Mok/Art/SyntyStory/GangDistinct"+i+"-"+m+".mat");mats[m]=mat;}r.sharedMaterials=mats;}i++;
 }
 EditorSceneManager.MarkSceneDirty(main);EditorSceneManager.SaveScene(main);
 var bank=EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath,OpenSceneMode.Additive);EditorSceneManager.SaveScene(bank,"Logs/Bank-before-role-"+stamp+".unity",true);var d=bank.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();
 var body=d.player.ragdoll.animator.transform;SyntyStoryUpgrade.Skin(body,Hoodie,"PlayerPrologue");var skins=body.GetComponentsInChildren<SkinnedMeshRenderer>(true);foreach(var extra in skins.Skip(1))extra.enabled=false;foreach(var r in body.GetComponentsInChildren<MeshRenderer>(true))r.enabled=false;d.player.avatarRenderers=new Renderer[]{skins[0]};EditorUtility.SetDirty(d.player);
 EditorSceneManager.MarkSceneDirty(bank);EditorSceneManager.SaveScene(bank);EditorSceneManager.CloseScene(bank,true);
 string prefab="Assets/Scripts/Mok/Art/Player/DeliveryPlayer.prefab";var root=PrefabUtility.LoadPrefabContents(prefab);try{Player(root.GetComponent<PlayerAvatar>(),"PlayerPrefab");PrefabUtility.SaveAsPrefabAsset(root,prefab);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();File.WriteAllText("Logs/Role-visual-apply.txt","Player main/prefab/prologue replaced; gang templates distinct; original rigs preserved.");
 }
 public static void RefinePlayers(){var main=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");foreach(var a in main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlayerAvatar>(true)))Player(a,"PlayerMain");EditorSceneManager.MarkSceneDirty(main);EditorSceneManager.SaveScene(main);
 var bank=EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath,OpenSceneMode.Additive);var d=bank.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();SyntyStoryUpgrade.Skin(d.player.ragdoll.animator.transform,Hoodie,"PlayerPrologue",false,true);EditorSceneManager.MarkSceneDirty(bank);EditorSceneManager.SaveScene(bank);File.WriteAllText("Logs/City-motion-layout.txt","A "+d.cityCarStart.position+" B "+d.cityCarEnd.position+" arrival "+d.story.cityArrivalSeconds+" pan "+d.story.cityPanSeconds);EditorSceneManager.CloseScene(bank,true);
 string prefab="Assets/Scripts/Mok/Art/Player/DeliveryPlayer.prefab";var root=PrefabUtility.LoadPrefabContents(prefab);try{Player(root.GetComponent<PlayerAvatar>(),"PlayerPrefab");PrefabUtility.SaveAsPrefabAsset(root,prefab);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();}
 public static System.Collections.IEnumerator Verify(){
 var player=UnityEngine.Object.FindFirstObjectByType<PlayerCombat>();var a=player.avatar;var b=UnityEngine.Object.FindFirstObjectByType<BrokerMission>();var tutorial=UnityEngine.Object.FindFirstObjectByType<StoryTutorial>();
 void Check(bool ok,string msg){if(!ok)throw new Exception(msg);File.AppendAllText("Logs/Role-visual-check.txt","PASS: "+msg+"\n");}
 File.WriteAllText("Logs/Role-visual-check.txt","");Check(a.animator.isHuman&&a.ragdoll.IsReady,"player humanoid and ragdoll remain connected");Check(a.GetComponentsInChildren<SkinnedMeshRenderer>().All(r=>AssetDatabase.GetAssetPath(r.sharedMesh).Contains("SyntyStory/Player")),"gameplay player uses Synty mesh");
 void Shot(Transform root,string name){var camera=new GameObject("Role preview camera").AddComponent<Camera>();camera.transform.position=root.position+root.forward*3+root.right*1.5f+Vector3.up*1.3f;camera.transform.LookAt(root.position+Vector3.up*.95f);var rt=new RenderTexture(960,720,24);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(960,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,960,720),0,0);tex.Apply();File.WriteAllBytes("Logs/Role-"+name+".png",tex.EncodeToPNG());RenderTexture.active=old;UnityEngine.Object.Destroy(tex);camera.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(camera.gameObject);}
 float ready=Time.time+2;while(Time.time<ready)yield return null;File.AppendAllText("Logs/Role-visual-check.txt",string.Join(";",a.GetComponentsInChildren<SkinnedMeshRenderer>().Select(r=>AssetDatabase.GetAssetPath(r.sharedMesh)))+" Animator "+a.animator.enabled+" state "+a.animator.GetCurrentAnimatorStateInfo(0).fullPathHash+" shoulder "+a.animator.GetBoneTransform(HumanBodyBones.LeftUpperArm).position+" elbow "+a.animator.GetBoneTransform(HumanBodyBones.LeftLowerArm).position+" hand "+a.animator.GetBoneTransform(HumanBodyBones.LeftHand).position+"\n");foreach(var r in a.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=r.sharedMesh;var baked=new Mesh();r.BakeMesh(baked);baked.RecalculateBounds();var bounds=new Bounds(mesh.vertices[0],Vector3.zero);foreach(var v in mesh.vertices)bounds.Encapsulate(v);File.AppendAllText("Logs/Role-visual-check.txt",r.name+" cpu="+bounds+" baked="+baked.bounds+" bones="+string.Join(";",r.bones.Where(t=>t.name.Contains("Arm")).Select(t=>t.name+":"+t.position))+"\n");UnityEngine.Object.Destroy(baked);}Shot(a.transform,"player");var enemy=UnityEngine.Object.Instantiate(b.enemyTemplate.gameObject,player.transform.position+player.transform.right*4,Quaternion.identity);foreach(var c in enemy.GetComponentsInChildren<MonoBehaviour>())c.enabled=false;enemy.SetActive(true);yield return null;Shot(enemy.transform,"gang");UnityEngine.Object.Destroy(enemy);
 var inbox=UnityEngine.Object.FindFirstObjectByType<StoryPhoneInbox>();inbox.AutoOpenEnabled=false;var cycle=UnityEngine.Object.FindFirstObjectByType<DayNightCycle>();cycle.EnterNightPreparation();yield return null;var notice=UnityEngine.Object.FindFirstObjectByType<DeliveryRequestNotice>();var message=(string)typeof(DeliveryRequestNotice).GetField("message",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(notice);Check(message=="낮 영업 종료 · 휴대폰 문자와 미션 앱을 확인하세요.","night notice text survives source encoding");
 UnityEngine.ScreenCapture.CaptureScreenshot("Logs/Role-night-notice.png");float until=Time.time+.3f;while(Time.time<until)yield return null;
 a.ragdoll.Launch(Vector3.up*2,1);until=Time.time+.2f;while(Time.time<until)yield return null;Check(a.ragdoll.IsActive,"new player skin follows ragdoll");until=Time.time+3f;while(Time.time<until)yield return null;Check(!a.ragdoll.IsActive,"player recovers from ragdoll");
 }
 public static void Reload(){foreach(var path in Directory.GetFiles("Assets/Scripts/Mok/Art/SyntyStory","Player*.asset")){var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);var v=m.vertices;var n=m.normals;var t=m.tangents;var uv=m.uv;var w=m.boneWeights;var b=m.bindposes;var triangles=Enumerable.Range(0,m.subMeshCount).Select(i=>m.GetTriangles(i)).ToArray();m.Clear();m.vertices=v;m.normals=n;m.tangents=t;m.uv=uv;m.boneWeights=w;m.bindposes=b;m.subMeshCount=triangles.Length;for(int i=0;i<triangles.Length;i++)m.SetTriangles(triangles[i],i);m.RecalculateBounds();m.UploadMeshData(false);EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();}
 public static void Inspect(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Single);string s="";
 foreach(var t in UnityEngine.Object.FindObjectsByType<Text>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(!string.IsNullOrEmpty(t.text))s+=t.name+" active="+t.gameObject.activeInHierarchy+" font="+(t.font?t.font.name:"")+" text="+t.text+"\n";
 foreach(var a in UnityEngine.Object.FindObjectsByType<PlayerAvatar>(FindObjectsInactive.Include,FindObjectsSortMode.None)){s+="PLAYER "+a.name+"\n";foreach(var r in a.GetComponentsInChildren<Renderer>(true))s+=r.name+" "+r.GetType().Name+" enabled="+r.enabled+"\n";}
 foreach(var a in UnityEngine.Object.FindObjectsByType<CitizenCombat>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(a.name.Contains("Gang")||a.name.Contains("Template"))s+="ENEMY "+a.name+"\n";
 File.WriteAllText("Logs/Role-visual-inspect.txt",s);}
}}
